INSERT INTO purpose VALUES('surface-pretty','DEPTH_LIMIT','constant','Names the depth a value''s presentation is bounded at, so a value deeper than the limit is elided.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','Fidelity','enum','Names the fidelity a presentation''s text carries, so a node the walk met is recorded as faithful or approximate.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','Form','enum','Names the form a former takes, so a former''s sugared or explicit spelling is chosen.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','Presentation','struct','Holds the laid-out text a presentation''s walk produces, so the text''s fidelity and written names are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','Style','struct','Holds a form and a spelling together, so a presentation''s entry point takes them as one.',NULL,'fits','sound',NULL);
