INSERT INTO purpose VALUES('surface-pretty','Wildcards','enum','Names the wildcards a presentation''s text carries, so a node the walk met is recorded as faithful or approximate.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','WrittenName','struct','Holds a declaration''s name the text writes, so the name''s span is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','content_source::ContentSource','struct','Holds a checkpoint''s content table as the printer''s source, so a checked item''s signature is laid out in the one spelling every face shows.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-pretty','core_source::Constructors','struct','Holds the constructors'' names, so a parameterised constructor is written against its family.',NULL,'fits','sound',NULL);
